"""Unit tests for shipping cost calculator using pytest."""

import pytest
from shipping import (
    Package,
    calculate_shipping_cost,
    ShippingMethod,
    ShippingError,
    InvalidWeightError,
    InvalidDimensionError,
    UnsupportedDestinationError,
)


class TestShippingCostCalculation:
    """Test basic shipping cost calculations."""

    def test_basic_standard_domestic_shipment(self):
        """Test standard shipping for domestic package."""
        package = Package(weight_kg=2.0, length_cm=20, width_cm=10, height_cm=5)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 10.0

    def test_basic_express_domestic_shipment(self):
        """Test express shipping for domestic package."""
        package = Package(weight_kg=2.0, length_cm=20, width_cm=10, height_cm=5)
        cost = calculate_shipping_cost(package, ShippingMethod.EXPRESS, "domestic")
        assert cost == 20.0

    def test_basic_standard_international_shipment(self):
        """Test standard shipping for international package."""
        package = Package(weight_kg=2.0, length_cm=20, width_cm=10, height_cm=5)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "international")
        assert cost == 24.0

    def test_fragile_surcharge(self):
        """Test that fragile packages have surcharge applied."""
        package = Package(weight_kg=2.0, length_cm=20, width_cm=10, height_cm=5, fragile=True)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 17.5

    def test_overweight_surcharge(self):
        """Test that overweight packages have surcharge applied."""
        package = Package(weight_kg=35.0, length_cm=20, width_cm=10, height_cm=5)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 190.0

    def test_oversize_surcharge(self):
        """Test that oversized packages have surcharge applied."""
        package = Package(weight_kg=2.0, length_cm=80, width_cm=50, height_cm=50)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 20.0

    def test_multiple_surcharges(self):
        """Test that multiple surcharges are all applied."""
        package = Package(
            weight_kg=40.0,
            length_cm=80,
            width_cm=50,
            height_cm=50,
            fragile=True,
        )
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 232.5


class TestInvalidWeightError:
    """Test InvalidWeightError exceptions."""

    def test_negative_weight_raises_error(self):
        """Test that negative weight raises InvalidWeightError."""
        with pytest.raises(InvalidWeightError):
            calculate_shipping_cost(
                Package(weight_kg=-5.0, length_cm=20, width_cm=10, height_cm=5),
                ShippingMethod.STANDARD,
                "domestic",
            )

    def test_zero_weight_raises_error(self):
        """Test that zero weight raises InvalidWeightError."""
        with pytest.raises(InvalidWeightError):
            calculate_shipping_cost(
                Package(weight_kg=0, length_cm=20, width_cm=10, height_cm=5),
                ShippingMethod.STANDARD,
                "domestic",
            )

    def test_weight_exceeds_maximum_raises_error(self):
        """Test that weight over 100kg raises InvalidWeightError."""
        with pytest.raises(InvalidWeightError):
            calculate_shipping_cost(
                Package(weight_kg=101.0, length_cm=20, width_cm=10, height_cm=5),
                ShippingMethod.STANDARD,
                "domestic",
            )


class TestInvalidDimensionError:
    """Test InvalidDimensionError exceptions."""

    def test_zero_length_raises_error(self):
        """Test that zero length raises InvalidDimensionError."""
        with pytest.raises(InvalidDimensionError):
            calculate_shipping_cost(
                Package(weight_kg=2.0, length_cm=0, width_cm=10, height_cm=5),
                ShippingMethod.STANDARD,
                "domestic",
            )

    def test_negative_width_raises_error(self):
        """Test that negative width raises InvalidDimensionError."""
        with pytest.raises(InvalidDimensionError):
            calculate_shipping_cost(
                Package(weight_kg=2.0, length_cm=20, width_cm=-5, height_cm=5),
                ShippingMethod.STANDARD,
                "domestic",
            )

    def test_zero_height_raises_error(self):
        """Test that zero height raises InvalidDimensionError."""
        with pytest.raises(InvalidDimensionError):
            calculate_shipping_cost(
                Package(weight_kg=2.0, length_cm=20, width_cm=10, height_cm=0),
                ShippingMethod.STANDARD,
                "domestic",
            )


class TestUnsupportedDestinationError:
    """Test UnsupportedDestinationError exceptions."""

    def test_invalid_destination_string_raises_error(self):
        """Test that invalid destination raises UnsupportedDestinationError."""
        with pytest.raises(UnsupportedDestinationError):
            calculate_shipping_cost(
                Package(weight_kg=2.0, length_cm=20, width_cm=10, height_cm=5),
                ShippingMethod.STANDARD,
                "moon",
            )

    def test_express_no_international(self):
        """Test that EXPRESS has no international support."""
        with pytest.raises(UnsupportedDestinationError):
            calculate_shipping_cost(
                Package(weight_kg=2.0, length_cm=20, width_cm=10, height_cm=5),
                ShippingMethod.EXPRESS,
                "international",
            )

    def test_overnight_no_international(self):
        """Test that OVERNIGHT has no international support."""
        with pytest.raises(UnsupportedDestinationError):
            calculate_shipping_cost(
                Package(weight_kg=2.0, length_cm=20, width_cm=10, height_cm=5),
                ShippingMethod.OVERNIGHT,
                "international",
            )


class TestRounding:
    """Test that costs are properly rounded to 2 decimal places."""

    def test_cost_rounds_properly(self):
        """Test that calculations round to 2 decimal places."""
        package = Package(weight_kg=1.234, length_cm=10, width_cm=10, height_cm=10)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 6.17


class TestEdgeCases:
    """Test edge cases that should work correctly."""

    def test_exact_overweight_threshold(self):
        """Test at exactly 30kg (no overweight surcharge)."""
        package = Package(weight_kg=30.0, length_cm=20, width_cm=10, height_cm=5)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 150.0

    def test_exact_oversize_threshold(self):
        """Test at exactly 150cm sum (no oversize surcharge)."""
        package = Package(weight_kg=2.0, length_cm=50, width_cm=50, height_cm=50)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 10.0

    def test_underweight_below_threshold(self):
        """Test weight below overweight threshold."""
        package = Package(weight_kg=1.0, length_cm=20, width_cm=10, height_cm=5)
        cost = calculate_shipping_cost(package, ShippingMethod.STANDARD, "domestic")
        assert cost == 5.0


