        (ShippingMethod.STANDARD, "international", 12.0),
        (ShippingMethod.EXPRESS, "domestic", 10.0),
    ])
    def test_valid_combinations_base_cost(self, method, destination, expected_rate):
        """Test base cost calculation for valid combinations."""
